#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions (defines DATA_TYPE, N, etc.)
#include "defines.hpp"

// include benchmark-specific definitions
#include "mvt.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Array initialization translated to Halide.
 *
 * Original C:
 *   for (i = 0; i < n; i++) {
 *     x1[i]  = (DATA_TYPE) (i % n) / n;
 *     x2[i]  = (DATA_TYPE) ((i + 1) % n) / n;
 *     y_1[i] = (DATA_TYPE) ((i + 3) % n) / n;
 *     y_2[i] = (DATA_TYPE) ((i + 4) % n) / n;
 *     for (j = 0; j < n; j++)
 *       A[i][j] = (DATA_TYPE) (i*j % n) / n;
 *   }
 *
 * We keep exactly these semantics but express them with Halide Funcs.
 */
static
void init_array(int n,
                Halide::Buffer<num_t, 1> x1,
                Halide::Buffer<num_t, 1> x2,
                Halide::Buffer<num_t, 1> y_1,
                Halide::Buffer<num_t, 1> y_2,
                Halide::Buffer<num_t, 2> A) {
    Var i("i"), j("j");

    Func init_x1("init_x1");
    Func init_x2("init_x2");
    Func init_y1("init_y1");
    Func init_y2("init_y2");
    Func init_A("init_A");

    // 1D vectors
    init_x1(i) = cast<num_t>(i % n) / cast<int>(n);
    init_x2(i) = cast<num_t>((i + 1) % n) / cast<int>(n);
    init_y1(i) = cast<num_t>((i + 3) % n) / cast<int>(n);
    init_y2(i) = cast<num_t>((i + 4) % n) / cast<int>(n);

    // 2D matrix A: C layout A[i][j] -> Halide A(j, i)
    //   - i is the row index in C.
    //   - j is the column index in C.
    //   - We map to A(j, i) so that the C "column" index j is the
    //     innermost (x) dimension in Halide; j is unit‑stride.
    init_A(j, i) = cast<num_t>((i * j) % n) / cast<int>(n);

    // Simple but effective schedule for initialization:
    Target target = get_host_target();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width < 1) vec_width = 1;

    // Vectorize and parallelize the 1D initializations.
    init_x1.vectorize(i, vec_width).parallel(i);
    init_x2.vectorize(i, vec_width).parallel(i);
    init_y1.vectorize(i, vec_width).parallel(i);
    init_y2.vectorize(i, vec_width).parallel(i);

    // For A, rows (i) are independent; columns (j) are unit‑stride.
    init_A.parallel(i).vectorize(j, vec_width);

    // Realize into the provided buffers
    init_x1.realize(x1);
    init_x2.realize(x2);
    init_y1.realize(y_1);
    init_y2.realize(y_2);
    init_A.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Buffers corresponding to:
    //   DATA_TYPE A[N][N];
    //   DATA_TYPE x1[N], x2[N], y_1[N], y_2[N];
    //
    // PolyBench uses A[i][j]; we map j -> dim 0 (x), i -> dim 1 (y).
    // So:
    //   A(i,j) in C   == A_buf(j, i) in Halide.
    Halide::Buffer<num_t, 2> A(n, n);     // (j, i)
    Halide::Buffer<num_t, 1> x1(n);
    Halide::Buffer<num_t, 1> x2(n);
    Halide::Buffer<num_t, 1> y_1(n);
    Halide::Buffer<num_t, 1> y_2(n);

    // ImageParams to feed into the Halide pipeline
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam x1_param(type_of<num_t>(), 1, "x1_param");
    ImageParam x2_param(type_of<num_t>(), 1, "x2_param");
    ImageParam y1_param(type_of<num_t>(), 1, "y1_param");
    ImageParam y2_param(type_of<num_t>(), 1, "y2_param");

    // Initialize data using a Halide-based initializer
    init_array(n, x1, x2, y_1, y_2, A);

    // Bind buffers to ImageParams
    A_param.set(A);
    x1_param.set(x1);
    x2_param.set(x2);
    y1_param.set(y_1);
    y2_param.set(y_2);

    // Halide translation of kernel_mvt:
    //
    // Original C kernel:
    //
    // for (i = 0; i < N; i++)
    //   for (j = 0; j < N; j++)
    //     x1[i] = x1[i] + A[i][j] * y_1[j];
    // for (i = 0; i < N; i++)
    //   for (j = 0; j < N; j++)
    //     x2[i] = x2[i] + A[j][i] * y_2[j];
    //
    // Mathematically:
    //   x1[i] = x1[i] + sum_j A[i][j] * y_1[j]
    //   x2[i] = x2[i] + sum_j A[j][i] * y_2[j]
    //
    // With our (j, i) mapping for A[i][j]:
    //   A[i][j]  -> A_param(j, i)
    //   A[j][i]  -> A_param(i, j)

    Var i("i");
    // Use the width of A (dim 0, corresponding to C's column index j) as
    // the reduction extent.
    RDom r(0, A.dim(0).extent(), "r");

    Func mvt_x1("mvt_x1");
    Func mvt_x2("mvt_x2");

    // First loop nest: accumulate into x1
    //
    // x1[i] = x1[i] + sum_j A[i][j] * y1[j]
    //       = x1_param(i) + sum_r A_param(r, i) * y1_param(r)
    mvt_x1(i) = x1_param(i);
    mvt_x1(i) += A_param(r, i) * y1_param(r);

    // Second loop nest: accumulate into x2
    //
    // x2[i] = x2[i] + sum_j A[j][i] * y2[j]
    //       = x2_param(i) + sum_r A_param(i, r) * y2_param(r)
    mvt_x2(i) = x2_param(i);
    mvt_x2(i) += A_param(i, r) * y2_param(r);

    // --------------------------------------------------------------------
    // Optimized schedule
    // --------------------------------------------------------------------
    //
    // We target a modern x64 CPU with SIMD and many cores.
    // Key ideas:
    //   * For the first matvec (x1), we want the reduction over r (C's j)
    //     to be the innermost loop, because A_param(r, i) and y1_param(r)
    //     are contiguous in r (x‑dimension of A).
    //   * For the second matvec (x2), we want the loops ordered as
    //       for r (C's j)   // outer
    //         for i         // inner
    //     so that A_param(i, r) walks the x‑dimension (unit‑stride) as i
    //     varies, giving contiguous access to rows of A[j][*] and x2[i].
    //   * We vectorize along the unit‑stride dimension and parallelize
    //     only along provably independent dimensions.
    //
    // NOTE: For reductions, reordering i and r is semantics-preserving
    // because + is associative/commutative up to FP roundoff.

    Target target = get_host_target();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width < 1) vec_width = 1;

    // ------------------------------
    // Schedule for mvt_x1
    // ------------------------------
    //
    // We want:
    //   for (i in parallel) {
    //     acc = x1[i];
    //     for (r vectorized) {
    //       acc += A[r, i] * y1[r];
    //     }
    //     x1[i] = acc;
    //   }
    //
    // Make mvt_x1 a top-level (root) computation, then:
    //   - reorder update vars to [r, i] so that i is outer, r inner
    //   - parallelize across i (rows)
    //   - vectorize across r (columns / reduction dim)
    mvt_x1.compute_root();
    mvt_x1.vectorize(i, vec_width).parallel(i);

    mvt_x1.update()
          // Reorder vars from innermost outwards: r inner, i outer.
          // This makes the loop nest:
          //   for i (outer, parallel)
          //     for r (inner, vectorized)
          .reorder(r, i)
          .parallel(i)
          .vectorize(r, vec_width);

    // ------------------------------
    // Schedule for mvt_x2
    // ------------------------------
    //
    // We want something like:
    //   for (r = 0..N-1) {      // outer
    //     t = y2[r];
    //     for (i vectorized) {  // inner, unit-stride for A(i, r) & x2(i)
    //       x2[i] += A[i, r] * t;
    //     }
    //   }
    //
    // This corresponds to dims [i, r] (i innermost, r outermost) for
    // the update step of mvt_x2.
    mvt_x2.compute_root();
    mvt_x2.vectorize(i, vec_width);  // cheap 1D init, mostly bandwidth

    mvt_x2.update()
          // Reorder update vars to [i, r] (i inner, r outer),
          // giving:
          //   for r (outer)
          //     for i (inner, vectorized)
          .reorder(i, r)
          .vectorize(i, vec_width);
    // We keep mvt_x2's reduction sequential in r to avoid parallel
    // reductions or extra temporary storage. Its memory access pattern
    // is still cache-friendly (contiguous in i for A_param(i, r) and
    // x2(i)) and benefits from SIMD.

    // JIT-compile the two Funcs with the same target.
    mvt_x1.compile_jit(target);
    mvt_x2.compile_jit(target);

    // Time the kernel execution (both x1 and x2 updates)
    auto start = std::chrono::high_resolution_clock::now();

    // Realize back into x1 and x2 buffers (in-place relative to the C view).
    // Note: x1_param/x2_param point at the same underlying memory, but
    // Halide only reads from the ImageParams in the pure definition and
    // never in the reduction update, so this aliasing is safe.
    mvt_x1.realize(x1);
    mvt_x2.realize(x2);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optional: print results to stderr (similar spirit to PolyBench print_array)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print x1
        for (int idx = 0; idx < n; idx++) {
            std::cerr << x1(idx) << '\n';
        }
        // Print x2
        for (int idx = 0; idx < n; idx++) {
            std::cerr << x2(idx) << '\n';
        }
    }

    // Print timing (seconds) to stdout
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
