 *   }
 *
 * We keep exactly the same numerical initialization; only the
 * Halide layout (which dimension is x/y) is an implementation
 * detail and is handled consistently below.
 */
static
void init_array(int n,
                Halide::Buffer<num_t, 1> x1,
                Halide::Buffer<num_t, 1> x2,
                Halide::Buffer<num_t, 1> y_1,
                Halide::Buffer<num_t, 1> y_2,
                Halide::Buffer<num_t, 2> A) {
    Var i("i"), j("j");

    Func init_x1("init_x1");
    Func init_x2("init_x2");
    Func init_y1("init_y1");
    Func init_y2("init_y2");
    Func init_A("init_A");

    // 1D vectors
    init_x1(i) = cast<num_t>(i % n) / cast<int>(n);
    init_x2(i) = cast<num_t>((i + 1) % n) / cast<int>(n);
    init_y1(i) = cast<num_t>((i + 3) % n) / cast<int>(n);
    init_y2(i) = cast<num_t>((i + 4) % n) / cast<int>(n);

    // 2D matrix A: C layout A[i][j] -> Halide A(j, i)
    // (j is the fastest‑varying dimension in memory, matching the
    //  inner j–loop of the first matvec.)
    init_A(j, i) = cast<num_t>((i * j) % n) / cast<int>(n);

    // Realize into the provided buffers
    init_x1.realize(x1);
    init_x2.realize(x2);
    init_y1.realize(y_1);
    init_y2.realize(y_2);
    init_A.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Buffers corresponding to:
    //   DATA_TYPE A[N][N];
    //   DATA_TYPE x1[N], x2[N], y_1[N], y_2[N];
    //
    // PolyBench uses A[i][j]; we map j -> dim 0 (x), i -> dim 1 (y).
    // This makes the column index j the unit‑stride dimension in
    // memory, which is ideal for the first matvec.
    Halide::Buffer<num_t, 2> A(n, n);     // (j, i)
    Halide::Buffer<num_t, 1> x1(n);
    Halide::Buffer<num_t, 1> x2(n);
    Halide::Buffer<num_t, 1> y_1(n);
    Halide::Buffer<num_t, 1> y_2(n);

    // ImageParams to feed into the Halide pipeline
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam x1_param(type_of<num_t>(), 1, "x1_param");
    ImageParam x2_param(type_of<num_t>(), 1, "x2_param");
    ImageParam y1_param(type_of<num_t>(), 1, "y1_param");
    ImageParam y2_param(type_of<num_t>(), 1, "y2_param");

    // Initialize data using a Halide-based initializer
    init_array(n, x1, x2, y_1, y_2, A);

    // Bind buffers to ImageParams
    A_param.set(A);
    x1_param.set(x1);
    x2_param.set(x2);
    y1_param.set(y_1);
    y2_param.set(y_2);

    // Halide translation of kernel_mvt:
    //
    // Original C kernel:
    //
    // for (i = 0; i < N; i++)
    //   for (j = 0; j < N; j++)
    //     x1[i] = x1[i] + A[i][j] * y_1[j];
    // for (i = 0; i < N; i++)
    //   for (j = 0; j < N; j++)
    //     x2[i] = x2[i] + A[j][i] * y_2[j];
    //
    // Mathematically:
    //   x1[i] = x1[i] + sum_j A[i][j] * y_1[j]
    //   x2[i] = x2[i] + sum_j A[j][i] * y_2[j]
    //
    // With our (j, i) mapping for A[i][j]:
    //   A[i][j]  -> A_param(j, i)
    //   A[j][i]  -> A_param(i, j)

    Var i("i");
    // Use the width of A (dim 0, corresponding to j) as the reduction extent.
    RDom r(0, A.dim(0).extent(), "r");

    Func mvt_x1("mvt_x1");
    Func mvt_x2("mvt_x2");

    // First loop nest: accumulate into x1
    //
    // x1[i] = x1[i] + sum_r A[i][r] * y_1[r]
    //        = x1[i] + sum_r A_param(r, i) * y1_param(r)
    mvt_x1(i) = x1_param(i);
    mvt_x1(i) += A_param(r, i) * y1_param(r);

    // Second loop nest: accumulate into x2
    //
    // x2[i] = x2[i] + sum_r A[r][i] * y_2[r]
    //        = x2[i] + sum_r A_param(i, r) * y2_param(r)
    mvt_x2(i) = x2_param(i);
    mvt_x2(i) += A_param(i, r) * y2_param(r);

    // -----------------------
    // Scheduling / optimization
    // -----------------------
    //
    // We target the host and choose a natural SIMD width for num_t.
    Target target = get_host_target();
    const int vec_width = std::max(1, target.natural_vector_size(type_of<num_t>()));

    // ---- mvt_x1: x1[i] = x1[i] + sum_j A[i][j] * y1[j] ----
    //
    // We want:
    //   - Outer loop over i (rows), inner loop over r (columns).
    //   - Each row i is completely independent, so we parallelize over i.
    //   - For each fixed i, r is the innermost loop and iterates over the
    //     unit‑stride dimension (j) of A_param(j, i), giving good locality.
    //
    // Default update order is pure vars outer, reduction vars inner, i.e.
    //   for i:
    //     for r:
    //       ...
    // To make this explicit and robust against other transformations,
    // we reorder the update so that r is inner.
    mvt_x1.compute_root();
    mvt_x1.update()
        // Arguments are listed from innermost to outermost. This puts
        // r inside i:  for i (parallel) { for r { ... } }
        .reorder(r, i)
        // Parallelize across rows i; each thread updates a disjoint
        // element x1[i], so there are no races.
        .parallel(i);

    // ---- mvt_x2: x2[i] = x2[i] + sum_j A[j][i] * y2[j] ----
    //
    // Access pattern A_param(i, r) with the original i-outer, r-inner
    // order would be strided in memory, because dim 0 of A is j, not i.
    // For better locality we:
    //   - Make 'r' (the row index of A[j][i]) the outer loop.
    //   - Make 'i' (the column index) the inner loop, so that we walk
    //     A_param(i, r) contiguously in the unit‑stride dimension.
    //   - Strip-mine i into tiles and vectorize the inner piece.
    //   - Parallelize across i-tiles inside each r, which is safe since
    //     each (r, i) pair updates a distinct x2[i].
    //
    // Resulting high-level structure:
    //   for r in [0, N):                  // rows of A
    //     t = y2[r];                      // reused across i
    //     parallel for io over tiles of i:
    //       for ii within tile:
    //         x2[i] += A_param(i, r) * t;
    mvt_x2.compute_root();

    Var io("io"), ii("ii");
    const int tile_i = 128;  // coarse tile size for i; tuned for cache / threads

    mvt_x2.update()
        // Make 'i' innermost, 'r' just outside:
        //   for r:
        //     for i:
        //       ...
        .reorder(i, r)
        // Strip-mine i into (io, ii): i = io * tile_i + ii.
        .split(i, io, ii, tile_i)
        // 'ii' is now the true innermost loop; vectorize across it so
        // that we load contiguous A_param(i, r) and x2[i].
        .vectorize(ii, vec_width)
        // Parallelize across tiles of i. The parallel loop is:
        //   for r:
        //     parallel for io:
        //       for ii:
        //         ...
        // which uses the thread pool once per r, but avoids races because
        // each (r, io, ii) triple updates a unique x2 element.
        .parallel(io);

    // JIT-compile the two Funcs for the chosen target
    mvt_x1.compile_jit(target);
    mvt_x2.compile_jit(target);

    // Time the kernel execution (both x1 and x2 updates)
    auto start = std::chrono::high_resolution_clock::now();

    // Realize back into x1 and x2 buffers (in-place relative to the C view)
    mvt_x1.realize(x1);
    mvt_x2.realize(x2);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optional: print results to stderr (similar spirit to PolyBench print_array)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print x1
        for (int idx = 0; idx < n; idx++) {
            std::cerr << x1(idx) << '\n';
        }
        // Print x2
        for (int idx = 0; idx < n; idx++) {
            std::cerr << x2(idx) << '\n';
        }
    }

    // Print timing (seconds) to stdout
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
