    A_param.set(A);
    x1_param.set(x1);
    x2_param.set(x2);
    y1_param.set(y_1);
    y2_param.set(y_2);

    // Halide translation of kernel_mvt:
    //
    // Original C kernel:
    //
    // for (i = 0; i < N; i++)
    //   for (j = 0; j < N; j++)
    //     x1[i] = x1[i] + A[i][j] * y_1[j];
    // for (i = 0; i < N; i++)
    //   for (j = 0; j < N; j++)
    //     x2[i] = x2[i] + A[j][i] * y_2[j];
    //
    // Mathematically:
    //   x1[i] = x1[i] + sum_j A[i][j] * y_1[j]
    //   x2[i] = x2[i] + sum_j A[j][i] * y_2[j]
    //
    // With our (j, i) mapping for A[i][j]:
    //   A[i][j]  -> A_param(j, i)
    //   A[j][i]  -> A_param(i, j)
    //
    // We use a 1D RDom over the contiguous j-dimension (dim 0 of A_param).
    Var i("i");
    RDom r(0, A.dim(0).extent(), "r"); // r corresponds to j

    Func mvt_x1("mvt_x1");
    Func mvt_x2("mvt_x2");

    // First mat-vec: x1[i] = x1[i] + sum_j A[i][j] * y_1[j]
    // Using our mapping: A[i][j] -> A_param(j, i) == A_param(r, i)
    mvt_x1(i) = x1_param(i);
    mvt_x1(i) += A_param(r, i) * y1_param(r);

    // Second mat-vec: x2[i] = x2[i] + sum_j A[j][i] * y_2[j]
    // Using our mapping: A[j][i] -> A_param(i, j) == A_param(i, r)
    mvt_x2(i) = x2_param(i);
    mvt_x2(i) += A_param(i, r) * y2_param(r);

    // --------------------------------------------------------------------
    // Optimized schedule
    //
    // Goals:
    //   - Exploit row-major storage of A(j, i) (j contiguous) for x1.
    //   - For x2, reorder the reduction so that A(i, r) is accessed
    //     row-major (r fixed, i walks contiguously).
    //   - Parallelize over i (rows) to use all cores.
    //   - Vectorize along the unit-stride dimension (j for x1, i for x2).
    //   - Preserve original numerical semantics.
    // --------------------------------------------------------------------

    // Target information for a reasonable SIMD width.
    Target target = get_host_target();
    const int vec_width = std::max(1, target.natural_vector_size(type_of<num_t>()));

    // Tile size over i (rows) for parallelism and cache locality.
    // 64 is a reasonable default on modern CPUs.
    const int tile_i = 64;

    // We introduce tiling variables for i and r in the reduction.
    Var io1("io1"), ii1("ii1");
    RVar ro1("ro1"), ri1("ri1");

    Var io2("io2"), ii2("ii2");

    // -------------------------
    // Schedule for mvt_x1
    // x1[i] = x1[i] + sum_r A(r, i) * y1[r]
    // Access pattern:
    //   - For fixed i, A(r, i) walks r along dim 0 (contiguous) -> good locality.
    // -------------------------

    // Compute the whole x1 vector at the root and tile across i for parallelism.
    mvt_x1.compute_root()
          .split(i, io1, ii1, tile_i)
          .parallel(io1);

    // Update (reduction) step:
    //
    //  - Split i into tiles (io1, ii1) as above.
    //  - Split r into (ro1, ri1) so we can vectorize the inner part ri1.
    //  - Reorder so that:
    //       outermost:  io1   (parallelized)
    //       then:       ii1
    //       then:       ro1
    //       innermost:  ri1   (vectorized over contiguous r)
    //
    // This yields a loop nest conceptually like:
    //
    //   parallel for io1:
    //     for ii1:
    //       for ro1:
    //         vectorized for ri1:
    //           i  = io1*tile_i + ii1
    //           r  = ro1*vec_width + ri1
    //           x1[i] += A(r, i) * y1[r];
    //
    mvt_x1.update()
          .split(i, io1, ii1, tile_i)
          .split(r, ro1, ri1, vec_width)
          .reorder(ri1, ro1, ii1, io1)
          .vectorize(ri1)
          .parallel(io1);

    // -------------------------
    // Schedule for mvt_x2
    // x2[i] = x2[i] + sum_r A(i, r) * y2[r]
    //
    // Default nesting (i-outer, r-inner) would access A(i, r) with
    // r varying on the slow (dim 1) axis, causing strided loads.
    //
    // We want r outer, i inner:
    //
    //   for r:
    //     for i:
    //       x2[i] += A(i, r) * y2[r];
    //
    // For fixed r, A(i, r) varies i along dim 0 (contiguous).
    // -------------------------

    // Compute x2 at root and tile over i for parallelism; we will reorder
    // the update so that r is outer and i (ii2) is inner.
    mvt_x2.compute_root()
          .split(i, io2, ii2, tile_i)
          .parallel(io2);

    // Update step:
    //
    //  - Split i into tiles (io2, ii2).
    //  - Reorder so that:
    //       outermost:  r
    //       then:       io2  (parallel tile index)
    //       innermost:  ii2  (vectorized over contiguous i)
    //
    // This yields:
    //
    //   for r:
    //     parallel for io2:
    //       for ii2:
    //         i = io2*tile_i + ii2;
    //         x2[i] += A(i, r) * y2[r];
    //
    mvt_x2.update()
          .split(i, io2, ii2, tile_i)
          .reorder(ii2, io2, r)    // ii2 innermost, then io2, then r outermost
          .vectorize(ii2, vec_width)
          .parallel(io2);

    // JIT-compile the two Funcs with the chosen target
    mvt_x1.compile_jit(target);
    mvt_x2.compile_jit(target);

    // Time the kernel execution (both x1 and x2 updates)
    auto start = std::chrono::high_resolution_clock::now();

    // Realize back into x1 and x2 buffers (in-place relative to the C view)
    mvt_x1.realize(x1);
    mvt_x2.realize(x2);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

