    mvt_x2(i) += A_param(i, r) * y2_param(r);

    // ------------------------------------------------------------------
    // Scheduling: improve parallelism and locality while preserving math
    // ------------------------------------------------------------------
    //
    // We target a modern x86_64 with multiple cores and SIMD.
    // Strategy:
    //   - For mvt_x1 (A * y1):
    //       * Each output element x1[i] is an independent reduction => we can
    //         safely parallelize across i.
    //       * Access pattern A_param(r, i): for fixed i, we walk r (j)
    //         along the unit-stride dimension of A (good locality).
    //   - For mvt_x2 (A^T * y2):
    //       * Naively, x2[i] += A_param(i, r) * y2[r] reads A down a column
    //         with large stride.
    //       * We reorder the reduction update to iterate r outermost and i
    //         innermost: for each row r, we sweep i across contiguous memory
    //         in A(j=r, i), and vectorize over i.
    //       * We keep this reduction sequential in r to avoid races on x2.
    //
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // --- Schedule for mvt_x1: parallel over i (rows), default reduction over r (cols).
    mvt_x1.compute_root();
    // Pure definition: one read of x1_param(i) per i; parallel is fine.
    mvt_x1.parallel(i);
    // Update definition: main work; each i reduces independently over r.
    mvt_x1.update()
          .parallel(i);
    // We rely on the compiler to auto-vectorize the innermost loop over r,
    // which reads A_param(r, i) and y1_param(r) contiguously.

    // --- Schedule for mvt_x2: reorder reduction to get row-major traversal, SIMD on i.
    mvt_x2.compute_root();
    // For the update step, change loop order from (i outer, r inner) to
    // (r outer, i inner) so that for each row r we sweep i contiguously.
    mvt_x2.update()
          .reorder(i, r)          // arguments: innermost -> outermost; i becomes innermost
          .vectorize(i, vec_width);
    // We keep mvt_x2 sequential in r to avoid the complexity of parallel
    // reductions over x2. For large problems, mvt_x1 (which is parallel)
    // will already utilize multiple cores well, and mvt_x2 benefits from
    // improved cache and SIMD efficiency.

    // JIT-compile the two Funcs for the chosen target
    mvt_x1.compile_jit(target);
    mvt_x2.compile_jit(target);

    // Time the kernel execution (both x1 and x2 updates)
    auto start = std::chrono::high_resolution_clock::now();

    // Realize back into x1 and x2 buffers (in-place relative to the C view).
    // Note: x1_param/x2_param are bound to the same underlying buffers,
    // but the pipeline only reads x1/x2 once in the pure definition and
    // never again during the reductions, so this aliasing is semantically
    // equivalent to the in-place C code.
    mvt_x1.realize(x1);
    mvt_x2.realize(x2);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optional: print results to stderr (similar spirit to PolyBench print_array)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print x1
        for (int idx = 0; idx < n; idx++) {
            std::cerr << x1(idx) << '\n';
        }
        // Print x2
        for (int idx = 0; idx < n; idx++) {
            std::cerr << x2(idx) << '\n';
        }
    }

    // Print timing (seconds) to stdout
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
